"""Report the shape of secret-looking values in .codx/project.json, never the value."""
import hashlib
import json
import os

PATH = "/home/codx-junior-projects/codx-junior/codx-junior-platform/.codx/project.json"

print("exists:", os.path.isfile(PATH), "size:", os.path.getsize(PATH) if os.path.exists(PATH) else 0)

with open(PATH, "r", encoding="utf-8") as fh:
    data = json.load(fh)

KEYS = ("token", "secret", "password", "key", "credential", "pat", "auth")


def mask(value):
    text = str(value)
    digest = hashlib.sha256(text.encode("utf-8", "ignore")).hexdigest()[:8]
    kind = "unknown"
    for prefix in ("ghp_", "gho_", "ghu_", "ghs_", "github_pat_", "glpat-", "sk-"):
        if text.startswith(prefix):
            kind = f"prefix {prefix}"
            break
    placeholder = any(word in text.lower() for word in ("example", "changeme", "xxx", "your-", "placeholder"))
    return f"len={len(text)} {kind} sha256[:8]={digest} placeholder_like={placeholder}"


def walk(node, path):
    if isinstance(node, dict):
        for key, value in node.items():
            here = f"{path}.{key}" if path else key
            if isinstance(value, (dict, list)):
                walk(value, here)
            elif value and any(word in str(key).lower() for word in KEYS):
                print(f"{here} = {mask(value)}")
    elif isinstance(node, list):
        for idx, value in enumerate(node):
            walk(value, f"{path}[{idx}]")


walk(data, "")
print("\ntop-level keys:", sorted(data.keys())[:40])

